        this.advanceStage();
      }
    } else if (s.type === 'combat') {
      const alive = this.enemies.filter(e => e.health > 0);
      if (alive.length === 0 && this.enemies.length > 0) {
        mc.progress++;
        this.log(`Wave cleared (${mc.progress}/${s.waves}).`);
        this.radio.chime();
        for (const e of [...this.enemies]) this.scene.remove(e.mesh);
