    if (this.player.inCar) {
      this.player.exitCar(this.city);
    } else {
      const car = this.player.tryEnterCar(this.cars.filter(c => c.stealable || c.owned));
      if (car) {
        if (car.stolen) this.setWanted(Math.max(this.wanted, 1));
        this.radio.setEngine(0, true);
      }
