  }

  // --- save / load ------------------------------------------------------------
  saveGame() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify({
        money: Math.floor(this.player.money),
        respect: this.respect,
        missionIdx: this.missions.missionIdx,
        health: this.player.health,
      }));
