    } catch (e) { /* corrupt save: start fresh */ }
  }

  // --- main loop ----------------------------------------------------------------
  run() {
    let last = performance.now();
    let frame = 0;
    const tick = (t) => {
      const dt = Math.min(0.05, (t - last) / 1000);
      last = t;
      frame++;
