        if (rel > RAM_SPEED && involvesPlayerOrPolice) {
          const dmg = rel * 1.4;
          other.damage(dmg, this);
          this.damage(dmg * 0.6, other);
          this.rammedBy = { car: other, relSpeed: rel };
          other.rammedBy = { car: this, relSpeed: rel };
        } else if (rel > 1) {
