  autopilot(dt, opts) {
    const { city, cars, now } = opts;
    const graph = city.graph;
    if (this.wrecked) return { throttle: 0, steer: 0 };

    const following = !!this.followTarget && !this.followTarget.wrecked;
    const targetPos = following
